old:
if !attached.turn_finished {
    return Ok(false);
}
let run = host.run(run_id)?;
Ok(matches!(
    run.state,
    AgentRunState::Executing | AgentRunState::AwaitingUser | AgentRunState::Repairing
) && gate_satisfied(run.completion.acceptance_criteria)
